1	import { useState } from "react";
2	import { Activity as ActivityIcon, Loader2, AlertCircle } from "lucide-react";
3	import SidebarLayout from "@/components/SidebarLayout";
4	import { Card, CardContent } from "@/components/ui/card";
5	import { Button } from "@/components/ui/button";
6	import { Skeleton } from "@/components/ui/skeleton";
7	import ActivityItem from "@/components/ActivityItem";
8	import { useActivityFeed } from "@/hooks/useActivityFeed";
9	import { useTeam } from "@/hooks/useTeam";
10	
11	// ─── Filter tabs ──────────────────────────────────────────────────────────────
12	
13	const FILTERS = ["All", "Tasks", "Notes", "Stages", "Applications", "Members"] as const;
14	type Filter = (typeof FILTERS)[number];
15	
16	// ─── Skeletons ────────────────────────────────────────────────────────────────
17	
18	function ActivitySkeleton() {
19	  return (
20	    <div className="space-y-3 p-4">
21	      {[1, 2, 3, 4].map((i) => (
22	        <div key={i} className="flex items-center gap-3">
23	          <Skeleton className="h-8 w-8 rounded-full shrink-0" />
24	          <Skeleton className="h-12 flex-1 rounded-lg" />
25	        </div>
26	      ))}
27	    </div>
28	  );
29	}
30	
31	// ─── Main page ────────────────────────────────────────────────────────────────
32	
33	const Activity = () => {
34	  const { team, isLoading: teamLoading } = useTeam();
35	  const teamId = team?.id ?? null;
36	
37	  const [activeFilter, setActiveFilter] = useState<Filter>("All");
38	
39	  const { activities, isLoading, isFetching, hasMore, loadMore, error } =
40	    useActivityFeed(teamId, activeFilter);
41	
42	  const showLoading = isLoading || (teamLoading && !teamId);
43	
44	  return (
45	    <SidebarLayout>
46	      <main className="w-full px-6 sm:px-8 lg:px-10 py-8">
47	        {/* Header */}
48	        <h1 className="text-2xl font-bold text-foreground mb-1">Activity</h1>
49	        <p className="text-sm text-muted-foreground mb-5">
50	          See what your team has been up to.
51	        </p>
52	
53	        {/* Filter tabs */}
54	        <div className="flex flex-wrap gap-1.5 mb-5">
55	          {FILTERS.map((f) => (
56	            <button
57	              key={f}
58	              onClick={() => setActiveFilter(f)}
59	              className={
60	                activeFilter === f
61	                  ? "px-3 h-7 rounded-full text-xs font-semibold bg-primary text-primary-foreground transition-colors"
62	                  : "px-3 h-7 rounded-full text-xs font-medium text-muted-foreground hover:text-foreground hover:bg-muted/60 transition-colors"
63	              }
64	            >
65	              {f}
66	            </button>
67	          ))}
68	        </div>
69	
70	        {/* No team state */}
71	        {!teamLoading && !teamId && (
72	          <div className="flex flex-col items-center justify-center py-16 space-y-4 text-center">
73	            <div className="rounded-xl bg-muted/50 p-4">
74	              <ActivityIcon className="h-7 w-7 text-muted-foreground/50" />
75	            </div>
76	            <div className="space-y-1">
77	              <p className="text-sm font-medium">No team yet</p>
78	              <p className="text-sm text-muted-foreground max-w-xs">
79	                Create or join a team to see activity here.
80	              </p>
81	            </div>
82	          </div>
83	        )}
84	
85	        {/* Loading skeleton */}
86	        {showLoading && (
87	          <Card className="border border-border/60 shadow-sm">
88	            <ActivitySkeleton />
89	          </Card>
90	        )}
91	
92	        {/* Error state */}
93	        {!showLoading && error && (
94	          <Card className="border-destructive/50">
95	            <CardContent className="py-8 text-center">
96	              <AlertCircle className="h-8 w-8 text-destructive mx-auto mb-2" />
97	              <p className="text-sm text-muted-foreground">Failed to load data. Please refresh the page.</p>
98	            </CardContent>
99	          </Card>
100	        )}
101	
102	        {/* Empty state */}
103	        {!showLoading && teamId && activities.length === 0 && (
104	          <div className="flex flex-col items-center justify-center py-16 space-y-4 text-center">
105	            <div className="rounded-xl bg-muted/50 p-4">
106	              <ActivityIcon className="h-7 w-7 text-muted-foreground/50" />
107	            </div>
108	            <div className="space-y-1">
109	              <p className="text-sm font-medium">No activity yet</p>
110	              <p className="text-sm text-muted-foreground max-w-xs">
111	                Activity from your team will appear here as things happen.
112	              </p>
113	            </div>
114	          </div>
115	        )}
116	
117	        {/* Activity list */}
118	        {!showLoading && teamId && activities.length > 0 && (
119	          <div>
120	            <Card className="border border-border/60 shadow-sm">
121	              <CardContent className="p-0">
122	                <div className="divide-y divide-border/50">
123	                  {activities.map((activity) => (
124	                    <div key={activity.id} className="px-4">
125	                      <ActivityItem activity={activity} compact={false} />
126	                    </div>
127	                  ))}
128	                </div>
129	
130	                {/* Load more */}
131	                {hasMore && (
132	                  <div className="flex justify-center px-4 py-3 border-t border-border/50">
133	                    <Button
134	                      variant="ghost"
135	                      size="sm"
136	                      onClick={loadMore}
137	                      disabled={isFetching}
138	                      className="text-xs text-muted-foreground"
139	                    >
140	                      {isFetching ? (
141	                        <Loader2 className="h-3.5 w-3.5 animate-spin mr-1.5" />
142	                      ) : null}
143	                      Load more
144	                    </Button>
145	                  </div>
146	                )}
147	              </CardContent>
148	            </Card>
149	          </div>
150	        )}
151	      </main>
152	    </SidebarLayout>
153	  );
154	};
155	
156	export default Activity;
157	
