108	
109	const Team = () => {
110	  const { user } = useAuth();
111	  const navigate = useNavigate();
112	  const { team, members, invitations, myRole, isLoading, error, refetch } = useTeam();
113	
114	  const [inviteEmail, setInviteEmail] = useState("");
115	  const [inviteRole, setInviteRole] = useState<"admin" | "member">("member");
116	  const [isSendingInvite, setIsSendingInvite] = useState(false);
117	  const [revokingId, setRevokingId] = useState<string | null>(null);
118	  const [removingId, setRemovingId] = useState<string | null>(null);
119	  const [updatingRoleId, setUpdatingRoleId] = useState<string | null>(null);
120	
121	  // New state
122	  const [leaveDialogOpen, setLeaveDialogOpen] = useState(false);
123	  const [revokeDialogTarget, setRevokeDialogTarget] = useState<TeamInvitation | null>(null);
124	  const [removeDialogTarget, setRemoveDialogTarget] = useState<TeamMember | null>(null);
125	  const [isLeavingTeam, setIsLeavingTeam] = useState(false);
126	  const [teamNameInput, setTeamNameInput] = useState("");
127	  const [isSavingTeamName, setIsSavingTeamName] = useState(false);
128	
129	  const canManage = myRole === "owner" || myRole === "admin";
130	
131	  async function handleInvite(e: React.FormEvent) {
132	    e.preventDefault();
133	    if (!inviteEmail.trim() || !team?.id) return;
134	
135	    setIsSendingInvite(true);
136	    try {
137	      const { data: { session } } = await supabase.auth.getSession();
138	      if (!session?.access_token) throw new Error("Not authenticated");
139	
140	      const res = await fetch(
141	        `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/send-team-invite`,
142	        {
143	          method: "POST",
144	          headers: {
145	            "Content-Type": "application/json",
146	            "Authorization": `Bearer ${session.access_token}`,
147	            "apikey": import.meta.env.VITE_SUPABASE_ANON_KEY,
148	          },
149	          body: JSON.stringify({
150	            team_id: team.id,
151	            email: inviteEmail.trim().toLowerCase(),
152	            role: inviteRole,
153	          }),
154	        }
155	      );
156	
157	      const json = await res.json();
158	      if (!res.ok) throw new Error(json.error || "Failed to send invitation");
159	
160	      toast.success(`Invitation sent to ${inviteEmail.trim()}`);
161	      setInviteEmail("");
162	      refetch();
163	    } catch (err: unknown) {
164	      const msg = err instanceof Error ? err.message : "Failed to send invitation";
165	      toast.error(msg);
166	    } finally {
167	      setIsSendingInvite(false);
168	    }
169	  }
170	
171	  async function handleConfirmRevoke() {
172	    if (!revokeDialogTarget) return;
173	    const { id, email } = revokeDialogTarget;
174	    setRevokingId(id);
175	    setRevokeDialogTarget(null);
176	    try {
177	      const { error } = await (supabase as any)
178	        .from("team_invitations")
179	        .update({ status: "revoked" })
180	        .eq("id", id);
181	
182	      if (error) throw error;
183	
184	      toast.success(`Invitation to ${email} revoked`);
185	      refetch();
186	    } catch (err: unknown) {
187	      toast.error("Failed to revoke invitation");
188	    } finally {
189	      setRevokingId(null);
190	    }
191	  }
192	
193	  async function handleChangeRole(member: TeamMember, newRole: TeamRole) {
194	    if (newRole === member.role) return;
195	    setUpdatingRoleId(member.id);
196	    try {
197	      const { error } = await (supabase as any)
198	        .from("team_members")
199	        .update({ role: newRole })
200	        .eq("id", member.id);
201	
202	      if (error) throw error;
203	
204	      toast.success(`Role updated to ${ROLE_LABELS[newRole]}`);
205	      refetch();
206	    } catch (err: unknown) {
207	      toast.error("Failed to update role");
208	    } finally {
209	      setUpdatingRoleId(null);
210	    }
211	  }
212	
213	  async function handleRemoveMember(member: TeamMember) {
214	    setRemovingId(member.id);
215	    try {
216	      const { error } = await (supabase as any)
217	        .from("team_members")
218	        .delete()
219	        .eq("id", member.id);
220	
221	      if (error) throw error;
222	
223	      toast.success("Member removed from team");
224	      refetch();
