231	
232	  async function handleLeaveTeam() {
233	    if (!user?.id || !team?.id) return;
234	    setIsLeavingTeam(true);
235	    try {
236	      const myMember = members.find((m) => m.user_id === user.id);
237	      if (!myMember) throw new Error("You are not a member of this team");
238	
239	      const { error } = await (supabase as any)
240	        .from("team_members")
241	        .delete()
242	        .eq("id", myMember.id);
243	
244	      if (error) throw error;
245	
246	      toast.success("You have left the team");
247	      navigate("/");
248	    } catch (err: unknown) {
249	      const msg = err instanceof Error ? err.message : "Failed to leave team";
250	      toast.error(msg);
251	      setIsLeavingTeam(false);
252	    }
253	  }
254	
255	  async function handleSaveTeamName() {
256	    const trimmed = teamNameInput.trim();
257	    if (!trimmed || !team?.id) return;
258	    setIsSavingTeamName(true);
259	    try {
260	      const { error } = await (supabase as any)
261	        .from("teams")
