271	      toast.error("Failed to update team name");
272	    } finally {
273	      setIsSavingTeamName(false);
274	    }
275	  }
276	
277	  const pendingInvitations = invitations.filter((inv) => inv.status === "pending");
278	
279	  const { data: dashboard, isLoading: dashLoading } = useTeamDashboard(team?.id ?? null);
280	
281	  const statCards = [
282	    {
283	      icon: Briefcase,
284	      label: "Total Jobs",
285	      value: dashboard?.totalJobs ?? 0,
286	    },
287	    {
288	      icon: FileText,
289	      label: "Active Candidates",
290	      value: dashboard?.activeCandidates ?? 0,
291	    },
292	    {
293	      icon: CheckSquare,
294	      label: "Pending Tasks",
295	      value: dashboard?.pendingTasks ?? 0,
296	    },
297	    {
298	      icon: Users,
299	      label: "Team Members",
300	      value: dashboard?.memberCount ?? 0,
301	    },
302	  ];
303	
304	  return (
305	    <SidebarLayout>
306	      <main className="w-full px-6 sm:px-8 lg:px-10 py-8">
