308	        <div className="flex items-center justify-between mb-1">
309	          <div>
310	            <h1 className="text-2xl font-bold text-foreground">Team</h1>
311	            {team && (
312	              <p className="text-sm text-muted-foreground mt-0.5">{team.name}</p>
313	            )}
314	          </div>
315	          {myRole !== "owner" && myRole !== null && (
316	            <Button
317	              variant="outline"
318	              size="sm"
