320	              onClick={() => setLeaveDialogOpen(true)}
321	              disabled={isLeavingTeam}
322	            >
323	              {isLeavingTeam ? (
324	                <Loader2 className="h-3.5 w-3.5 animate-spin" />
325	              ) : (
326	                <LogOut className="h-3.5 w-3.5" />
327	              )}
328	              Leave team
329	            </Button>
330	          )}
331	        </div>
332	        <p className="text-sm text-muted-foreground mb-6">
333	          Manage your team members, activity, and settings.
334	        </p>
335	
336	        {/* Error state */}
337	        {!isLoading && error && (
338	          <Card className="border-destructive/50 mb-6">
339	            <CardContent className="py-8 text-center">
340	              <AlertCircle className="h-8 w-8 text-destructive mx-auto mb-2" />
341	              <p className="text-sm text-muted-foreground">Failed to load data. Please refresh the page.</p>
342	            </CardContent>
343	          </Card>
344	        )}
345	
346	        {/* ── Tabs ── */}
347	        <Tabs defaultValue="overview" className="w-full">
348	          <TabsList className="w-full justify-start border-b border-border bg-transparent px-0 rounded-none h-auto mb-0">
349	            <TabsTrigger value="overview" className={TAB_TRIGGER_CLASS}>
350	              <BarChart3 className="h-3.5 w-3.5 mr-1.5" />
351	              Overview
352	            </TabsTrigger>
353	            <TabsTrigger value="members" className={TAB_TRIGGER_CLASS}>
354	              <Users className="h-3.5 w-3.5 mr-1.5" />
355	              Members
356	            </TabsTrigger>
357	            {canManage && (
358	              <TabsTrigger value="settings" className={TAB_TRIGGER_CLASS}>
359	                <SettingsIcon className="h-3.5 w-3.5 mr-1.5" />
360	                Settings
361	              </TabsTrigger>
362	            )}
363	          </TabsList>
364	
365	          {/* ---------------------------------------------------------------- */}
366	          {/* Tab 1: Overview                                                   */}
367	          {/* ---------------------------------------------------------------- */}
368	          <TabsContent value="overview" className="mt-6 space-y-4">
369	            {!team ? (
370	              <Card className="border border-border/60 shadow-sm">
371	                <CardContent className="py-12 text-center">
372	                  <div className="rounded-xl bg-muted/50 p-4 inline-flex mb-3">
373	                    <Users className="h-7 w-7 text-muted-foreground/50" />
374	                  </div>
375	                  <p className="text-sm font-medium text-foreground mb-1">No team yet</p>
376	                  <p className="text-sm text-muted-foreground max-w-xs mx-auto">
377	                    You are not part of a team. Ask your team owner to invite you.
378	                  </p>
379	                </CardContent>
380	              </Card>
381	            ) : (
382	              <>
383	                {/* Stats row */}
384	                <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
385	                  {statCards.map(({ icon: Icon, label, value }) => (
386	                    <Card key={label} className="border border-border/60 shadow-sm">
387	                      <CardContent className="p-4">
388	                        <div className="flex items-center gap-2.5 mb-2">
389	                          <div className="h-8 w-8 rounded-lg bg-primary/10 flex items-center justify-center shrink-0">
390	                            <Icon className="h-4 w-4 text-primary" />
391	                          </div>
392	                        </div>
393	                        {dashLoading ? (
394	                          <Skeleton className="h-7 w-12 mb-1" />
395	                        ) : (
396	                          <p className="text-2xl font-bold text-foreground">{value}</p>
397	                        )}
398	                        <p className="text-xs text-muted-foreground">{label}</p>
399	                      </CardContent>
400	                    </Card>
401	                  ))}
402	                </div>
403	
404	                {/* Recent Activity */}
405	                <Card className="border border-border/60 shadow-sm">
406	                  <CardHeader className="pb-2 pt-4">
407	                    <div className="flex items-center justify-between">
408	                      <CardTitle className="text-sm font-semibold">Recent Activity</CardTitle>
409	                      <Link
410	                        to="/activity"
411	                        className="inline-flex items-center gap-1 text-xs text-primary hover:text-primary/80 transition-colors font-medium"
412	                      >
413	                        View all
414	                        <ArrowRight className="h-3 w-3" />
415	                      </Link>
416	                    </div>
417	                  </CardHeader>
418	                  <CardContent className="pb-3">
419	                    {dashLoading ? (
420	                      <div className="space-y-2">
421	                        {[1, 2, 3].map((i) => (
422	                          <Skeleton key={i} className="h-9 w-full rounded-lg" />
423	                        ))}
424	                      </div>
425	                    ) : !dashboard?.recentActivity.length ? (
426	                      <p className="text-sm text-muted-foreground py-2">No activity yet</p>
427	                    ) : (
428	                      <div className="divide-y divide-border/40">
429	                        {dashboard.recentActivity.map((activity) => (
430	                          <ActivityItem key={activity.id} activity={activity} compact />
431	                        ))}
432	                      </div>
433	                    )}
434	                  </CardContent>
435	                </Card>
436	
437	                {/* Task summary by assignee */}
438	                {!dashLoading && dashboard?.tasksByAssignee && dashboard.tasksByAssignee.length > 0 && (
439	                  <Card className="border border-border/60 shadow-sm">
440	                    <CardHeader className="pb-2 pt-4">
441	                      <CardTitle className="text-sm font-semibold">Task Summary by Member</CardTitle>
442	                    </CardHeader>
443	                    <CardContent className="p-0">
444	                      <Table>
445	                        <TableHeader>
446	                          <TableRow>
447	                            <TableHead className="text-xs">Member</TableHead>
448	                            <TableHead className="text-xs text-right">Pending</TableHead>
449	                            <TableHead className="text-xs text-right">Completed</TableHead>
450	                          </TableRow>
451	                        </TableHeader>
452	                        <TableBody>
453	                          {dashboard.tasksByAssignee.map((row) => {
454	                            const member = members.find((m) => m.user_id === row.user_id);
455	                            const label = member?.email ?? row.user_id.slice(0, 8) + "…";
456	                            return (
