1	import { useEffect, useRef, useState } from "react";
2	import { useQuery, useQueryClient } from "@tanstack/react-query";
3	import { supabase } from "@/integrations/supabase/client";
4	
5	export interface ActivityItem {
6	  id: string;
7	  team_id: string;
8	  actor_id: string | null;
9	  action: string;
10	  entity_type: string | null;
11	  entity_id: string | null;
12	  metadata: Record<string, any>;
13	  created_at: string;
14	}
15	
16	const PAGE_SIZE = 50;
17	
18	/** Map action strings to the filter tab categories */
19	const ACTION_FILTER_MAP: Record<string, string[]> = {
20	  Tasks: ["task_created", "task_completed"],
21	  Notes: ["note_added"],
22	  Stages: ["stage_changed"],
23	  Applications: ["application_received"],
24	  Members: ["member_joined"],
25	};
26	
27	function getActionsForFilter(filter: string): string[] | null {
28	  if (filter === "All") return null;
29	  return ACTION_FILTER_MAP[filter] ?? null;
30	}
31	
32	export function useActivityFeed(
33	  teamId: string | null,
34	  filter: string = "All"
35	) {
36	  const queryClient = useQueryClient();
37	  const actions = getActionsForFilter(filter);
38	  const queryKey = ["activity-feed", teamId, filter];
39	
40	  // Cursor for pagination (oldest created_at in current set)
41	  const [before, setBefore] = useState<string | null>(null);
42	  const [hasMore, setHasMore] = useState(false);
43	
44	  // Accumulate pages locally so "Load more" appends
45	  const [allActivities, setAllActivities] = useState<ActivityItem[]>([]);
46	  const initialLoaded = useRef(false);
47	
48	  const { data, isLoading, isFetching, error } = useQuery<ActivityItem[]>({
49	    queryKey: [...queryKey, before],
50	    queryFn: async () => {
51	      if (!teamId) return [];
52	
53	      let q = (supabase as any)
54	        .from("activity_log")
55	        .select("*")
56	        .eq("team_id", teamId)
57	        .order("created_at", { ascending: false })
58	        .limit(PAGE_SIZE + 1); // +1 to detect hasMore
59	
60	      if (actions && actions.length > 0) {
61	        q = q.in("action", actions);
62	      }
63	      if (before) {
64	        q = q.lt("created_at", before);
65	      }
66	
67	      const { data: rows, error } = await q;
68	      if (error) throw error;
69	      return (rows ?? []) as ActivityItem[];
70	    },
71	    enabled: !!teamId,
72	    staleTime: 30_000,
73	  });
74	
75	  // Merge pages when data arrives
76	  useEffect(() => {
77	    if (!data) return;
78	
79	    const more = data.length > PAGE_SIZE;
80	    const page = more ? data.slice(0, PAGE_SIZE) : data;
81	    setHasMore(more);
82	
83	    if (!before) {
84	      // First page — reset
85	      setAllActivities(page);
86	      initialLoaded.current = true;
87	    } else {
88	      // Subsequent page — append
89	      setAllActivities((prev) => {
90	        const existingIds = new Set(prev.map((a) => a.id));
91	        const fresh = page.filter((a) => !existingIds.has(a.id));
92	        return [...prev, ...fresh];
93	      });
94	    }
95	  }, [data]);
96	
97	  // Reset when teamId or filter changes
98	  useEffect(() => {
99	    setBefore(null);
100	    setAllActivities([]);
101	    initialLoaded.current = false;
102	  }, [teamId, filter]);
103	
104	  // Realtime subscription — invalidate first-page query on new inserts
105	  useEffect(() => {
106	    if (!teamId) return;
107	
108	    const channel = supabase
109	      .channel(`activity-log-${teamId}`)
110	      .on(
111	        "postgres_changes",
112	        {
113	          event: "INSERT",
114	          schema: "public",
115	          table: "activity_log",
116	          filter: `team_id=eq.${teamId}`,
117	        },
118	        (payload) => {
119	          const newItem = payload.new as ActivityItem;
120	          // Prepend to the displayed list immediately (optimistic)
121	          setAllActivities((prev) => {
122	            if (prev.some((a) => a.id === newItem.id)) return prev;
123	            return [newItem, ...prev];
124	          });
125	          // Also invalidate so first-page re-fetches on next stale check
126	          queryClient.invalidateQueries({ queryKey: ["activity-feed", teamId, filter] });
127	        }
128	      )
129	      .subscribe();
130	
131	    return () => {
132	      supabase.removeChannel(channel);
133	    };
134	  }, [teamId, filter, queryClient]);
135	
136	  function loadMore() {
137	    if (!hasMore || isFetching) return;
138	    const last = allActivities[allActivities.length - 1];
139	    if (last) setBefore(last.created_at);
140	  }
141	
142	  return {
143	    activities: allActivities,
144	    isLoading: isLoading && allActivities.length === 0,
145	    isFetching,
146	    hasMore,
147	    loadMore,
148	    error,
149	  };
150	}
